window.GLOW_INDEX=[{"t":"Product","title":"Gentle Gel Cleanser","url":"products/gentle-gel-cleanser.html","img":"assets/img/products/gentle-gel-cleanser.svg","sub":"Cleansers","text":"A fresh, low-foam gel that lifts oil and sunscreen without a tight, squeaky finish. Cleansers Oily Combination Normal Excess oil Blemishes Visible pores Glycerin Panthenol Mild surfactants"},{"t":"Product","title":"Creamy Barrier Cleanser","url":"products/creamy-barrier-cleanser.html","img":"assets/img/products/creamy-barrier-cleanser.svg","sub":"Cleansers","text":"A milky, cushiony cleanser that leaves dry or reactive skin soft instead of tight. Cleansers Dry Sensitive Normal Dryness Sensitivity Ceramides Glycerin Fragrance-free"},{"t":"Product","title":"Niacinamide Clarifying Serum","url":"products/niacinamide-clarifying-serum.html","img":"assets/img/products/niacinamide-clarifying-serum.svg","sub":"Serums","text":"A silky serum built around niacinamide for a smoother-looking, more balanced complexion. Serums Oily Combination Normal Excess oil Visible pores Uneven tone Niacinamide 2-5% Zinc PCA Hyaluronic acid"},{"t":"Product","title":"Hyaluronic Hydration Serum","url":"products/hyaluronic-hydration-serum.html","img":"assets/img/products/hyaluronic-hydration-serum.svg","sub":"Serums","text":"A weightless water-gel that plumps the look of tired, dehydrated skin. Serums All skin types Dehydration Dryness Dullness Hyaluronic acid Sodium hyaluronate Panthenol"},{"t":"Product","title":"Vitamin C Brightening Serum","url":"products/vitamin-c-brightening-serum.html","img":"assets/img/products/vitamin-c-brightening-serum.svg","sub":"Serums","text":"A morning antioxidant serum that supports radiance and works alongside daily sunscreen. Serums Normal Combination Oily Dullness Uneven tone L-ascorbic acid 10-20% Vitamin E / ferulic acid Opaque pump or dropper"},{"t":"Product","title":"Ceramide Barrier Cream","url":"products/ceramide-barrier-cream.html","img":"assets/img/products/ceramide-barrier-cream.svg","sub":"Moisturizers","text":"A rich, comforting cream with skin-identical lipids for dry or easily irritated skin. Moisturizers Dry Sensitive Normal Dryness Sensitivity Ceramides NP, AP, EOP Cholesterol Fragrance-free"},{"t":"Product","title":"Lightweight Gel Moisturizer","url":"products/lightweight-gel-moisturizer.html","img":"assets/img/products/lightweight-gel-moisturizer.svg","sub":"Moisturizers","text":"A bouncy, oil-free gel-cream that hydrates without leaving a heavy film. Moisturizers Oily Combination Normal Excess oil Dehydration Glycerin Hyaluronic acid Non-comedogenic label"},{"t":"Product","title":"Daily Fluid Sunscreen SPF 50","url":"products/daily-fluid-sunscreen-spf50.html","img":"assets/img/products/daily-fluid-sunscreen-spf50.svg","sub":"Sunscreen","text":"A broad-spectrum fluid sunscreen that wears like a moisturizer and layers well. Sunscreen All skin types Sun protection Uneven tone Broad-spectrum label SPF 30 or higher Water resistance"},{"t":"Product","title":"Mineral Sensitive-Skin Sunscreen","url":"products/mineral-sensitive-sunscreen.html","img":"assets/img/products/mineral-sensitive-sunscreen.svg","sub":"Sunscreen","text":"A zinc-based sunscreen designed for skin that dislikes chemical filters. Sunscreen Sensitive Dry Normal Sensitivity Sun protection Zinc oxide Tinted options Fragrance-free"},{"t":"Product","title":"BHA Clarifying Exfoliant","url":"products/bha-clarifying-exfoliant.html","img":"assets/img/products/bha-clarifying-exfoliant.svg","sub":"Exfoliants & Treatments","text":"A leave-on salicylic acid liquid that helps clear congestion and smooth texture. Exfoliants & Treatments Oily Combination Blemishes Visible pores Excess oil Salicylic acid 0.5-2% Soothing extracts Low fragrance"},{"t":"Product","title":"Retinol Night Serum","url":"products/retinol-night-serum.html","img":"assets/img/products/retinol-night-serum.svg","sub":"Exfoliants & Treatments","text":"A beginner-strength retinol for smoother texture and fine lines, introduced slowly. Exfoliants & Treatments Normal Combination Oily Dry Fine lines Uneven tone Blemishes Retinol 0.1-0.3% Encapsulated retinol Airtight packaging"},{"t":"Product","title":"Peptide Eye Cream","url":"products/peptide-eye-cream.html","img":"assets/img/products/peptide-eye-cream.svg","sub":"Masks & Eye Care","text":"A cushiony eye cream that softens dry, fine lines and feels gentle near the eyes. Masks & Eye Care All skin types Fine lines Dryness Peptides Hyaluronic acid Ophthalmologist-tested"},{"t":"Product","title":"Soothing Hydrogel Mask","url":"products/soothing-hydrogel-mask.html","img":"assets/img/products/soothing-hydrogel-mask.svg","sub":"Masks & Eye Care","text":"A cooling, hydrating mask for a weekly reset when skin feels tired or tight. Masks & Eye Care All skin types Dry Sensitive Dryness Dullness Sensitivity Hyaluronic acid Centella asiatica No strong fragrance"},{"t":"Article","title":"How to Build a Simple Skincare Routine (Beginner's Guide)","url":"blog/simple-skincare-routine-for-beginners.html","img":"assets/img/articles/simple-skincare-routine-for-beginners.svg","sub":"Routines","text":"Three steps are enough to start: cleanse, moisturize and protect. Here is how to build from there without overwhelming your skin. Routines  A good routine is not a long one. Dermatology organisations consistently describe the same foundation: a gentle cleanser, a moisturizer and a daily sunscreen. Everything else is optional. The core three steps Cleanse. Remove oil, sweat and sunscreen with a gentle cleanser. Once or twice a day is plenty. Moisturize. Helps keep the skin barrier comfortable and hydrated. Protect. Broad-spectrum SPF 30 or higher every morning, even on cloudy days. A sample morning and evening Morning: cleanse (or just rinse with water), moisturizer, sunscreen. Evening: cleanse, moisturizer. That is a complete routine. Adding products the smart way When you are ready for an extra step, add one product at a time and wait a few weeks before adding another. If something irritates your skin you will know exactly what caused it. Choose one goal (hydration, tone, texture, breakouts). Pick one product aimed at that"},{"t":"Article","title":"How to Find Your Skin Type (and Why It Matters)","url":"blog/how-to-find-your-skin-type.html","img":"assets/img/articles/how-to-find-your-skin-type.svg","sub":"Skin Basics","text":"Dry, oily, combination, normal or sensitive: a quick at-home check helps you pick products that actually suit you. Skin Basics  Knowing your skin type saves money and prevents irritation. The five commonly used types are normal, dry, oily, combination and sensitive. The bare-face test Wash your face with a gentle cleanser, pat dry and wait an hour without applying anything. Then check how your skin feels. Tight or flaky: likely dry. Shiny across the face: likely oily. Shiny in the T-zone only: likely combination. Comfortable and balanced: likely normal. Stinging, redness or reactions to many products: likely sensitive. Skin type versus skin condition Your skin type is largely genetic. A skin condition such as dehydration, breakouts or redness can change with the seasons, stress and your routine. Oily skin can still be dehydrated, which is why hydrating ingredients help every type. What to look for by type Dry: creamy cleansers, ceramides, richer moisturizers. Oily: gel cleansers, lightweight gel moisturizers, ni"},{"t":"Article","title":"Niacinamide Explained: What It Does and Who It Suits","url":"blog/niacinamide-explained.html","img":"assets/img/articles/niacinamide-explained.svg","sub":"Ingredients","text":"A friendly look at vitamin B3: the benefits research supports, sensible percentages and how to layer it. Ingredients  Niacinamide is a form of vitamin B3 and one of the most popular and well-studied cosmetic ingredients. It is valued because it is effective, affordable and generally gentle. What it may help with Supporting the skin barrier and reducing water loss. Making visible pores and shine look more controlled. Evening out the look of skin tone and mild marks. Calming the look of redness for some people. What percentage should you choose? Most products sit between 2 and 10 percent. Studies on tone, texture and barrier support commonly use around 2 to 5 percent, and higher numbers are not always better. Start low if your skin is sensitive. How to use it Apply after cleansing and before moisturizer, morning or evening. It layers well with hyaluronic acid, ceramides, retinoids and sunscreen. Possible side effects Some people notice flushing, tingling or small bumps, especially at higher concentration"},{"t":"Article","title":"Sunscreen 101: SPF, Broad-Spectrum and How Much to Apply","url":"blog/sunscreen-101-spf-explained.html","img":"assets/img/articles/sunscreen-101-spf-explained.svg","sub":"Sun Care","text":"What SPF actually measures, why broad-spectrum matters, and the common mistakes that leave skin under-protected. Sun Care  If you only add one product to your routine, make it sunscreen. Daily protection helps reduce the risk of sunburn and skin cancer and limits long-term signs of photoageing. What SPF means SPF measures protection against UVB, the rays that cause sunburn. SPF 30 filters roughly 97 percent of UVB and SPF 50 about 98 percent, so the jump is smaller than the numbers suggest. Correct application matters far more. Why broad-spectrum matters UVA rays penetrate deeper and drive ageing. A broad-spectrum label (or UVA-PA markings in some regions) shows the product protects against both. Labelling rules differ across the United States, United Kingdom, Canada and Europe, so check what is printed on your local product. Mineral or chemical? Mineral (zinc oxide, titanium dioxide): sits on the skin, often liked by sensitive skin, can leave a cast. Chemical (organic filters): thinner textures, often easi"},{"t":"Article","title":"Retinol for Beginners: How to Start Without Irritation","url":"blog/retinol-for-beginners.html","img":"assets/img/articles/retinol-for-beginners.svg","sub":"Ingredients","text":"A slow, sunscreen-first plan for introducing retinol, plus what to expect in the first twelve weeks. Ingredients  Retinoids are vitamin A derivatives with strong evidence for improving fine lines, texture and breakouts. Over-the-counter retinol is a gentler entry point than prescription options. Before you begin Use a good moisturizer and daily SPF first. Do not use retinoids if you are pregnant or trying to conceive. Ask your doctor. Patch test before using on your whole face. A gentle starting schedule Weeks 1-2: pea-sized amount, two nights a week. Weeks 3-4: three nights a week if skin is comfortable. Weeks 5+: increase gradually towards every other night or nightly. Cleanse, wait until skin is fully dry, then apply. Sandwiching retinol between two thin layers of moisturizer can help if you are sensitive. What to expect Mild dryness, flaking and tightness in the first weeks are common. Use a barrier cream and scale back if irritation lingers. Visible improvements usually take eight to twelve we"},{"t":"Article","title":"Vitamin C Serums: A Practical Buying and Using Guide","url":"blog/vitamin-c-serum-guide.html","img":"assets/img/articles/vitamin-c-serum-guide.svg","sub":"Ingredients","text":"Forms, percentages, packaging and when to apply, so you can choose a vitamin C that works and lasts. Ingredients  Vitamin C is an antioxidant that can help skin look brighter and more even, and it complements sunscreen in a morning routine. Forms and strengths L-ascorbic acid (10 to 20 percent) is the most studied form but is also the most unstable and can sting. Derivatives (such as ascorbyl glucoside or magnesium ascorbyl phosphate) are gentler and more stable, though sometimes less potent. Check the packaging Vitamin C breaks down with light and air. Choose opaque, airtight packaging, such as a pump, and note any expiry guidance. A serum that has turned dark orange or brown has oxidised. How to use it Apply to clean, dry skin in the morning. Follow with moisturizer, then sunscreen. If skin is sensitive, start every other day. What it pairs with Vitamin C works well with sunscreen, vitamin E and hyaluronic acid. If you use exfoliating acids or retinol, many people keep those for the evening to si"},{"t":"Article","title":"How to Layer Skincare Products in the Right Order","url":"blog/how-to-layer-skincare-products.html","img":"assets/img/articles/how-to-layer-skincare-products.svg","sub":"Routines","text":"Thinnest to thickest is the rule of thumb. Here is a clean morning and evening order you can follow. Routines  Layering is simpler than it looks. The general principle is to apply products from the thinnest, most watery texture to the thickest, so each step can reach the skin. Morning order Cleanser (or a water rinse) Antioxidant or hydrating serum Moisturizer Sunscreen, always last Evening order Cleanser (double cleanse if you wore sunscreen or makeup) Treatment such as retinol or an exfoliating acid, on the nights you use it Hydrating serum Moisturizer Do you need to wait between steps? Usually not. A few seconds to let a product settle is enough, though acids and retinoids can feel more comfortable on fully dry skin. Keep it manageable If you are using strong actives, do not layer several in one go. Alternate nights and let your moisturizer do the soothing work. "},{"t":"Article","title":"Your Skin Barrier: Ceramides, Hydration and Over-Exfoliation","url":"blog/skin-barrier-ceramides-and-hydration.html","img":"assets/img/articles/skin-barrier-ceramides-and-hydration.svg","sub":"Skin Basics","text":"Signs your barrier is struggling, and a calm, step-by-step approach to helping it recover. Skin Basics  The outermost layer of the skin works like a brick wall. Skin cells are the bricks, and lipids such as ceramides, cholesterol and fatty acids act as the mortar. When it is healthy, skin holds water and resists irritants. Signs the barrier is struggling Stinging when you apply products that used to feel fine Tightness, flaking or rough patches Redness or a shiny, tight look Sudden breakouts alongside dryness Common causes Over-exfoliating, stacking many actives, harsh cleansers, very hot water and cold, dry weather can all contribute. A calm reset Pause exfoliating acids, retinoids and scrubs. Switch to a gentle, fragrance-free cleanser. Use a ceramide-rich moisturizer morning and evening. Keep up with sunscreen every morning. Reintroduce actives slowly once skin feels comfortable again. When to get help If irritation lasts more than a couple of weeks, spreads or is painful, see a doctor"},{"t":"Category","title":"Cleansers","url":"category/cleansers.html","sub":"Shop category","text":"Gentle first steps that clean without stripping."},{"t":"Category","title":"Serums","url":"category/serums.html","sub":"Shop category","text":"Targeted, lightweight formulas for specific goals."},{"t":"Category","title":"Moisturizers","url":"category/moisturizers.html","sub":"Shop category","text":"Comfort, hydration and a stronger skin barrier."},{"t":"Category","title":"Sunscreen","url":"category/sunscreen.html","sub":"Shop category","text":"Daily protection that is a joy to wear."},{"t":"Category","title":"Exfoliants & Treatments","url":"category/exfoliants-treatments.html","sub":"Shop category","text":"Acids and retinoids for texture, clarity and tone."},{"t":"Category","title":"Masks & Eye Care","url":"category/masks-eye-care.html","sub":"Shop category","text":"Treat-yourself steps for comfort and radiance."},{"t":"Page","title":"About us","url":"about.html","sub":"Company","text":"about mission editorial standards team"},{"t":"Page","title":"Contact","url":"contact.html","sub":"Company","text":"contact email message support partnership"},{"t":"Page","title":"Affiliate disclosure","url":"affiliate-disclosure.html","sub":"Legal","text":"affiliate commission links disclosure FTC transparency"},{"t":"Page","title":"Privacy policy","url":"privacy-policy.html","sub":"Legal","text":"privacy data cookies GDPR rights"}];